import json
try:
    d=json.load(open('passage_catalog.json'))
    print('type:', type(d).__name__, '| count:', len(d) if hasattr(d,'__len__') else '?')
    # try to surface area/tag fields
    items = d if isinstance(d,list) else d.get('passages', d)
    if isinstance(items,dict): items=list(items.values())
    areas={}
    for p in items[:5000]:
        if isinstance(p,dict):
            for k in ('area','region','district','zone','tags'):
                if k in p:
                    v=p[k]
                    if isinstance(v,list):
                        for t in v: areas[str(t)]=areas.get(str(t),0)+1
                    else:
                        areas[str(v)]=areas.get(str(v),0)+1
    top=sorted(areas.items(), key=lambda x:-x[1])[:40]
    for k,v in top: print(f'{v:5d}  {k}')
except Exception as e:
    print('ERR', e)
"

